// Chart engine gallery: every series type in both presets, with export
// checks. Dev only (see charts.html for build / serve commands).
//
//   ?theme=dark|light|hc   ?preset=screen|publication   ?only=<figure id>   ?checks=1 (run exports, print results)

import '../src/styles/main.css';
import { EXP_COLOR, JOURNAL_SIZES, PALETTE, REF_COLOR, figureToolbar, render, toCsv, toPdf, toPng, toSvg, type Figure, type FigureSize, type Preset, type Series, type ToolbarHost } from '../src/charts';
import { card, toast } from '../src/ui/components';
import { h, mount } from '../src/ui/dom';

const params = new URLSearchParams(location.search);
const initialPreset = (params.get('preset') as Preset) || 'screen';
const only = params.get('only');

// --- data -----------------------------------------------------------------------------

const SPECTRA = spectraData();
const nm = SPECTRA.nm;
const sets = SPECTRA.sets.map(s => ({ ...s, total: s.total.map(v => v * 1e-18), lo: s.lo.map(v => v * 1e-18), hi: s.hi.map(v => v * 1e-18) }));
const toEv = (v: number) => 1239.84193 / v;

/** Deterministic pseudo-random numbers (mulberry32). */
function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function gauss(r: () => number): number {
  return Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
}

let experiment: { x: number[]; y: number[]; synthetic: boolean } = (() => {
  // stand-in until the real data (uv-vis/05-spectrum/CH2OO_Ting.dat, not redistributed) is fetched
  const x = nm.filter(v => v >= 280 && v <= 480);
  const ref = sets[0];
  const y = x.map(v => ref.total[nm.indexOf(v)] * 0.93 * (1 + 0.03 * Math.sin(v / 6)));
  return { x, y, synthetic: true };
})();

async function loadExperiment(): Promise<void> {
  try {
    const r = await fetch('/fs/C:/Users/16bto/Desktop/uv-vis/05-spectrum/CH2OO_Ting.dat');
    if (!r.ok) {
      return;
    }
    const rows = (await r.text()).trim().split(/\r?\n/).map(l => l.trim().split(/\s+/).map(Number)).filter(p => p.length >= 2 && p[1] > 0);
    rows.sort((a, b) => a[0] - b[0]);
    experiment = { x: rows.map(p => p[0]), y: rows.map(p => p[1]), synthetic: false };
  } catch {
    // keep the stand-in
  }
}

const SIGMA = 'σ / cm^{2} molecule^{−1}';
const secondary = { label: 'E / eV', toSecondary: toEv, fromSecondary: toEv };

function expSeries(): Series {
  return { type: 'line', x: experiment.x, y: experiment.y, label: experiment.synthetic ? 'experiment (stand-in)' : 'experiment', color: EXP_COLOR, dash: 'dashed', width: 1.1 };
}

// --- figures ----------------------------------------------------------------------------

function overlay(): Figure {
  const series: Series[] = [];
  sets.slice(0, 3).forEach(s => {
    series.push({ type: 'band', x: nm, lo: s.lo, hi: s.hi, group: s.label });
    series.push({ type: 'line', x: nm, y: s.total, label: s.label, group: s.label });
  });
  series.push(expSeries());
  return {
    panels: [{ x: { label: 'λ / nm', min: 250, max: 500 }, y: { label: SIGMA }, xSecondary: secondary, series }]
  };
}

function difference(): Figure {
  const top: Series[] = sets.slice(0, 3).map(s => ({ type: 'line', x: nm, y: s.total, label: s.label, group: s.label }));
  top.push(expSeries());
  const ref = sets[0];
  const z = 1.959964;
  const bottom: Series[] = [{ type: 'hline', value: 0, color: PALETTE[0], width: 1, group: ref.label }];
  sets.slice(1, 3).forEach(s => {
    const d = s.total.map((v, i) => v - ref.total[i]);
    const half = s.total.map((_, i) => z * Math.hypot((ref.hi[i] - ref.lo[i]) / (2 * z), (s.hi[i] - s.lo[i]) / (2 * z)));
    bottom.push({ type: 'band', x: nm, lo: d.map((v, i) => v - half[i]), hi: d.map((v, i) => v + half[i]), group: s.label });
    bottom.push({ type: 'line', x: nm, y: d, group: s.label });
  });
  return {
    layout: { kind: 'stack', sharedX: true },
    panelLabels: true,
    size: { widthIn: 3.25, heightIn: 3.4 },
    panels: [
      { x: { label: 'λ / nm', min: 250, max: 500 }, y: { label: SIGMA }, series: top, heightRatio: 2 },
      { x: { label: 'λ / nm', min: 250, max: 500 }, y: { label: 'Δσ / cm^{2} molecule^{−1}' }, series: bottom, heightRatio: 1, legend: 'none' }
    ]
  };
}

function histogram(): Figure {
  const r = rng(7);
  const sample = (n: number, mu: number, sd: number, skew: number) => Array.from({ length: n }, () => {
    const g = gauss(r);
    return mu + sd * g + skew * g * g;
  });
  const edges = Array.from({ length: 41 }, (_, i) => 2.6 + i * 0.05);
  const hist = (v: number[]) => {
    const c = new Array(edges.length - 1).fill(0);
    v.forEach(x => {
      const k = Math.floor((x - edges[0]) / 0.05);
      if (k >= 0 && k < c.length) {
        c[k]++;
      }
    });
    return c.map(n => n / (v.length * 0.05));
  };
  return {
    panels: [{
      x: { label: 'ΔE(S_{1}) / eV' }, y: { label: 'density / eV^{−1}' },
      series: [
        { type: 'histogram', edges, values: hist(sample(5000, 3.55, 0.22, 0.03)), style: 'filled', label: 'Wigner (n = 5000)' },
        { type: 'histogram', edges, values: hist(sample(1000, 3.62, 0.15, 0.01)), style: 'step', label: 'classical MD (n = 1000)' },
        { type: 'vline', value: 3.55, dash: 'dotted', color: PALETTE[0] }
      ]
    }]
  };
}

function longTrace(): Figure {
  const n = 100000;
  const r = rng(11);
  const t = new Float64Array(n);
  const e = new Float64Array(n);
  let drift = 0;
  for (let i = 0; i < n; i++) {
    t[i] = i * 0.001;
    drift += 0.002 * gauss(r);
    e[i] = 1.8 * Math.sin(t[i] / 7) + 0.6 * drift + 0.9 * gauss(r) + (i === 61803 ? 9 : 0);
  }
  return {
    panels: [{
      x: { label: 't / ps' }, y: { label: 'E_{pot} − ⟨E_{pot}⟩ / kcal mol^{−1}' },
      series: [{ type: 'line', x: t, y: e, label: 'GLE thermostat', width: 0.8 }]
    }]
  };
}

function parity(): Figure {
  const r = rng(3);
  const mk = (n: number, lo: number, hi: number, sd: number) => {
    const x = Array.from({ length: n }, () => lo + (hi - lo) * r());
    return { x, y: x.map(v => v + sd * gauss(r) + 0.02), e: x.map(() => 0.03 + 0.05 * r()) };
  };
  const s1 = mk(120, 3.0, 4.2, 0.07);
  const s2 = mk(120, 4.6, 6.4, 0.11);
  return {
    panels: [{
      equalAspect: true,
      x: { label: 'E_{ADC(3)} / eV' }, y: { label: 'E_{ML} / eV' },
      series: [
        { type: 'line', x: [2.5, 7], y: [2.5, 7], color: REF_COLOR, width: 0.75, dash: 'dashed' },
        { type: 'scatter', x: s1.x, y: s1.y, label: 'S_{1}', yErr: s1.e, size: 3 },
        { type: 'scatter', x: s2.x, y: s2.y, label: 'S_{2}', marker: 'square', size: 3 },
        { type: 'text', x: 6.4, y: 3.2, text: 'MAE = 0.064 eV', anchor: 'end' }
      ]
    }],
    size: { widthIn: 3.25, heightIn: 3.0 }
  };
}

function heatmap(): Figure {
  const gx = [-3, -2.5, -2, -1.5, -1, -0.5, 0];
  const gy = [-8, -7, -6, -5, -4, -3];
  const z = gy.map(ly => gx.map(lg => 0.055 + 0.03 * (lg + 1.6) ** 2 + 0.006 * (ly + 5.4) ** 2 + 0.004 * Math.max(0, lg + ly + 7)));
  const edges = (c: number[]) => [...c.map((v, i) => v - (i ? (v - c[i - 1]) / 2 : (c[1] - c[0]) / 2)), c[c.length - 1] + (c[c.length - 1] - c[c.length - 2]) / 2];
  return {
    panels: [{
      x: { label: 'log_{10} γ', ticks: gx }, y: { label: 'log_{10} λ', ticks: gy },
      legend: 'none',
      series: [{ type: 'heatmap', xEdges: edges(gx), yEdges: edges(gy), z, colormap: 'viridis', colorbarLabel: 'CV MAE / eV', annotate: v => v.toFixed(3) }]
    }],
    size: { widthIn: 3.25, heightIn: 2.6 }
  };
}

function sticks(): Figure {
  const states = [[3.42, 0.0021], [3.97, 0.0985], [5.63, 0.0074], [6.12, 0.0412], [6.58, 0.0213], [7.05, 0.0602], [7.48, 0.0127], [7.91, 0.0338]];
  const E = Array.from({ length: 601 }, (_, i) => 2.5 + i * 0.01);
  const width = 0.25;
  const y = E.map(e => states.reduce((a, [e0, f]) => a + 4.0e-17 * f * Math.exp(-0.5 * ((e - e0) / width) ** 2), 0));
  return {
    panels: [{
      x: { label: 'E / eV', min: 2.5, max: 8.5 }, y: { label: SIGMA }, y2: { label: 'f' },
      series: [
        { type: 'line', x: E, y, label: 'broadened (0.25 eV)' },
        { type: 'sticks', x: states.map(s => s[0]), y: states.map(s => s[1]), yAxis: 'right', label: 'oscillator strength', color: PALETTE[1], width: 1.25 }
      ]
    }]
  };
}

function smallMultiples(): Figure {
  const ref = sets[0];
  return {
    layout: { kind: 'grid', cols: 3, sharedX: true, sharedY: true },
    panelLabels: true,
    size: JOURNAL_SIZES['acs-2col'],
    panels: sets.slice(1, 4).map((s, i) => ({
      x: { label: 'λ / nm', min: 250, max: 480 }, y: { label: SIGMA },
      legend: 'auto' as const,
      series: [
        { type: 'band', x: nm, lo: ref.lo, hi: ref.hi, group: 'ref', color: REF_COLOR, opacity: 0.12 },
        { type: 'line', x: nm, y: ref.total, label: ref.label, group: 'ref', color: REF_COLOR, width: 1 },
        expSeries(),
        { type: 'band', x: nm, lo: s.lo, hi: s.hi, group: s.label, color: PALETTE[i + 1] },
        { type: 'line', x: nm, y: s.total, label: s.label, group: s.label, color: PALETTE[i + 1] }
      ] as Series[]
    }))
  };
}

function perf(): Figure {
  const r = rng(5);
  const series: Series[] = [];
  for (let k = 0; k < 10; k++) {
    const x = Float64Array.from({ length: 4000 }, (_, i) => i / 10);
    const y = Float64Array.from(x, v => Math.sin(v / (8 + k)) + 0.1 * k + 0.05 * gauss(r));
    series.push({ type: 'line', x, y, label: `trace ${k + 1}` });
  }
  const big = longTrace().panels[0].series[0];
  return {
    panels: [
      { x: { label: 't / ps' }, y: { label: 'signal' }, series, legend: 'outside-right' },
      { x: { label: 't / ps' }, y: { label: 'E / kcal mol^{−1}' }, series: [big] }
    ]
  };
}

interface Entry {
  id: string;
  title: string;
  subtitle: string;
  make: () => Figure;
}

const ENTRIES: Entry[] = [
  { id: 'overlay', title: 'UV-vis overlay', subtitle: 'three NEA spectra with 95 % CI bands, dashed experiment, eV on top', make: overlay },
  { id: 'difference', title: 'Overlay + difference', subtitle: 'stack, shared x, heightRatio [2, 1], zero line', make: difference },
  { id: 'histogram', title: 'Histogram comparison', subtitle: 'filled vs step, vertical reference line', make: histogram },
  { id: 'trace', title: '10⁵-point trace', subtitle: 'min/max decimation keeps the spike', make: longTrace },
  { id: 'parity', title: 'Parity plot', subtitle: 'equal aspect, error bars, two markers', make: parity },
  { id: 'heatmap', title: 'Grid search', subtitle: 'heatmap, annotation, colour bar', make: heatmap },
  { id: 'sticks', title: 'Sticks on y2', subtitle: 'oscillator strengths (right axis) under the broadened band', make: sticks },
  { id: 'multiples', title: 'Small multiples', subtitle: 'grid 3 × 1, shared x and y, reference in neutral ink', make: smallMultiples },
  { id: 'perf', title: 'Performance', subtitle: '10 × 4000 points + 10⁵ points, legend outside', make: perf }
];

// --- page -------------------------------------------------------------------------------

function download(name: string, data: string, encoding: 'utf8' | 'base64' | undefined): void {
  const bytes = encoding === 'base64' ? Uint8Array.from(atob(data), c => c.charCodeAt(0)) : new TextEncoder().encode(data);
  const a = h('a', { href: URL.createObjectURL(new Blob([bytes as BlobPart])), download: name });
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 2000);
}

const host: ToolbarHost = {
  studio: (async (method: string, p: any) => {
    if (method === 'saveFile') {
      download(p.defaultName, p.data, p.encoding);
      return p.defaultName;
    }
    if (method === 'sendToReport') {
      toast(`sendToReport: ${p.name} (pdf ${Math.round(((p.pdf?.length ?? 0) * 0.75) / 1024)} kB, png ${Math.round(((p.png?.length ?? 0) * 0.75) / 1024)} kB)`, 'success');
    }
    return undefined;
  }) as ToolbarHost['studio'],
  toast: (m, level) => toast(m, level)
};

const app = document.getElementById('app')!;
const state = new Map<string, { preset: Preset; size?: FigureSize }>();

function figureFor(e: Entry): Figure {
  const st = state.get(e.id)!;
  const fig = e.make();
  return { ...fig, preset: st.preset, size: st.size ?? fig.size };
}

const timings = h('span.muted');

function page(): void {
  const cards = ENTRIES.filter(e => !only || e.id === only).map(e => {
    state.set(e.id, { preset: initialPreset });
    const box = h('div.gallery-chart');
    let handle: ReturnType<typeof render> | undefined;
    const toolbar = figureToolbar({
      figure: () => figureFor(e),
      name: e.id,
      host,
      initialPreset,
      initialSize: e.make().size,
      caption: () => e.subtitle,
      onLayoutChange: (preset, size) => {
        state.set(e.id, { preset, size });
        handle?.update(figureFor(e));
      }
    });
    const c = card({ title: e.title, subtitle: e.subtitle, class: 'gallery-card' }, toolbar, box);
    c.dataset.id = e.id;
    requestAnimationFrame(() => {
      handle = render(box, figureFor(e), { onZoom: (p, a, b) => console.log('zoom', e.id, p, a, b) });
    });
    return c;
  });
  mount(app,
    h('div.gallery', null,
      h('header.gallery-head', null,
        h('h1', null, 'Chart engine gallery'),
        h('div.row', null,
          ['dark', 'light', 'hc'].map(t => h('button.btn.ghost', { type: 'button', onclick: () => (window as any).__setTheme?.(t) }, t)),
          h('button.btn.secondary', { type: 'button', onclick: () => void runChecks() }, 'Run export checks'))),
      timings,
      h('div.gallery-grid', { class: only ? 'single' : '' }, cards),
      h('section.gallery-checks', null, h('pre#check-log'), h('div#check-out'))));
  setTimeout(() => {
    const ms = [...document.querySelectorAll<HTMLElement>('.chart')].map(el => `${el.closest<HTMLElement>('.gallery-card')?.dataset.id}: ${el.dataset.renderMs} ms`);
    timings.textContent = `last render: ${ms.join(' · ')}`;
    document.body.dataset.timings = ms.join(';');
  }, 1500);
}

// --- export checks -------------------------------------------------------------------------

function log(line: string): void {
  document.getElementById('check-log')!.textContent += `${line}\n`;
}

function b64(bytes: Uint8Array): string {
  let s = '';
  for (let i = 0; i < bytes.length; i += 0x8000) {
    s += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  }
  return btoa(s);
}

async function runChecks(): Promise<void> {
  const out = document.getElementById('check-out')!;
  out.replaceChildren();
  const fig: Figure = { ...overlay(), preset: 'publication' };
  fig.panels[0].series.push({ type: 'text', x: 470, y: 1.0e-17, text: 'ν̃, Δ, ε_{max}', anchor: 'end' });
  try {
    const svg = toSvg(fig);
    log(`SVG: ${svg.length} chars, size ${/width="([\d.]+pt)" height="([\d.]+pt)"/.exec(svg)?.slice(1).join(' × ')}, contains var(): ${svg.includes('var(')}, <text> elements: ${(svg.match(/<text/g) ?? []).length}`);
    out.appendChild(h('div.check', null, h('h3', null, 'SVG'), h('img', { src: URL.createObjectURL(new Blob([svg], { type: 'image/svg+xml' })), style: 'width:468px;background:#fff' })));
    const t0 = performance.now();
    const png = await toPng(fig, { dpi: 600 });
    const img = new Image();
    img.src = URL.createObjectURL(new Blob([png as BlobPart], { type: 'image/png' }));
    await img.decode();
    const chunk = String.fromCharCode(...png.slice(37, 41));
    log(`PNG 600 dpi: ${img.naturalWidth} × ${img.naturalHeight} px (expected ${Math.round(3.25 * 600)} × ${Math.round(2.4 * 600)}), ${(png.length / 1024).toFixed(0)} kB, chunk after IHDR: ${chunk}, ${(performance.now() - t0).toFixed(0)} ms`);
    out.appendChild(h('div.check', null, h('h3', null, 'PNG (600 dpi, shown at 468 px)'), h('img', { src: img.src, style: 'width:468px' })));
    const t1 = performance.now();
    const pdf = await toPdf(fig);
    const raw = new TextDecoder('latin1').decode(pdf);
    const fonts = [...new Set(raw.match(/\/BaseFont\s*\/[A-Za-z0-9+_-]+/g) ?? [])];
    log(`PDF: ${(pdf.length / 1024).toFixed(0)} kB, /FontFile2 entries: ${(raw.match(/\/FontFile2/g) ?? []).length}, ${fonts.join(', ')}, ${(performance.now() - t1).toFixed(0)} ms`);
    const pdfjsUrl = '/out/webview-dev/pdf.min.mjs';
    const pdfjs: any = await import(pdfjsUrl);
    pdfjs.GlobalWorkerOptions.workerSrc = '/out/webview/pdf.worker.min.mjs';
    const doc = await pdfjs.getDocument({ data: pdf.slice() }).promise;
    const page1 = await doc.getPage(1);
    const tc = await page1.getTextContent();
    const text = tc.items.map((it: any) => it.str).join('|');
    log(`PDF text (pdf.js): ${text}`);
    log(`PDF text has λ: ${text.includes('λ')}, σ: ${text.includes('σ')}, Δ: ${text.includes('Δ')}, U+2212: ${text.includes('−')}`);
    const vp = page1.getViewport({ scale: 2 });
    const canvas = h('canvas', { width: String(vp.width), height: String(vp.height), style: 'width:468px;background:#fff' }) as HTMLCanvasElement;
    await page1.render({ canvasContext: canvas.getContext('2d')!, viewport: vp, canvas }).promise;
    out.appendChild(h('div.check', null, h('h3', null, 'PDF rendered by pdf.js'), canvas));
    const csv = toCsv(fig);
    log(`CSV: ${csv.split('\n').length - 2} data rows, header: ${csv.split('\n')[0]}`);
    out.appendChild(h('textarea#payload-svg', { hidden: true, value: svg }));
    out.appendChild(h('textarea#payload-png', { hidden: true, value: b64(png) }));
    out.appendChild(h('textarea#payload-pdf', { hidden: true, value: b64(pdf) }));
    document.body.dataset.checks = 'done';
  } catch (e) {
    log(`ERROR: ${e instanceof Error ? `${e.message}\n${e.stack}` : String(e)}`);
    document.body.dataset.checks = 'error';
  }
}

